using System.Net;
using System.Net.Http.Json;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using GnazzosWorld.Core.Commerce;
using GnazzosWorld.Core.Fulfillment;
using GnazzosWorld.Core.Identity;
using GnazzosWorld.Core.Orders;
using GnazzosWorld.Core.Payments;
using Xunit;

namespace GnazzosWorld.Api.Tests;

public sealed class FulfillmentApiTests:IDisposable
{
    private static CancellationToken Ct=>TestContext.Current.CancellationToken;
    private readonly string root=Path.Combine(Path.GetTempPath(),"gnazzo-fulfillment-api-"+Guid.NewGuid().ToString("N"));private readonly Clock clock=new();
    private static readonly OrderOwner A=new("https://fixture.auth0.com/","reader-a");private static string Key()=>Guid.NewGuid().ToString("N");
    private SqliteOrderStore Store()=>new(Path.Combine(root,Guid.NewGuid().ToString("N")+".db"),clock);
    private static SongRequest Draft()=>new(){Genre="Folk",Occasion="Synthetic anniversary",Story="Invented customer story",ContactName="Sample Reader",Email="reader@example.test"};
    private static OrderSnapshot Accept(SqliteOrderStore s){var q=s.CreateQuote(A,Draft());return s.Accept(A,new(q.Id,Key(),q.Request));}
    private void PayAndStart(SqliteOrderStore s,OrderSnapshot order)
    {
        var r=s.ReserveTestCheckout(A,order.Id,"stripe-test:acct_fixture","https://localhost/");s.AttachTestSession(r,new("cs_test_"+r.AttemptId,"https://checkout.stripe.com/c/"+r.AttemptId));
        var bytes=JsonSerializer.SerializeToUtf8Bytes(new{id="evt_"+r.AttemptId,@object="event",livemode=false,type="checkout.session.completed",data=new{@object=new{id="cs_test_"+r.AttemptId,@object="checkout.session",mode="payment",livemode=false,client_reference_id=r.AttemptId,metadata=new{order_id=order.Id},currency="usd",amount_total=order.TotalMinor,payment_status="paid",payment_intent="pi_fixture"}}});
        var timestamp=clock.Now.ToUnixTimeSeconds();var signature="t="+timestamp+",v1="+Convert.ToHexString(HMACSHA256.HashData(Encoding.UTF8.GetBytes("whsec_synthetic_fixture_secret_0123456789"),Encoding.ASCII.GetBytes(timestamp+".").Concat(bytes).ToArray()));
        s.ApplyVerifiedTestEvent(new StripeTestEventVerifier("whsec_synthetic_fixture_secret_0123456789",r.Scope,clock).Verify(bytes,signature)!);s.StartProductionForPaymentLab(order.Id,1);
    }
    private OrderSnapshot Ready(SqliteOrderStore s){var o=Accept(s);PayAndStart(s,o);return s.PublishReviewForLab(o.Id,2);}
    private static string PathFor(string id)=>"/api/v1/commerce/orders/"+id;
    private static async Task<DeliveryGrant> Grant(HttpClient c,string id,DeliveryDescriptor d,long version=4)
    {using var r=await c.PostAsJsonAsync(PathFor(id)+"/deliveries/"+d.Id+"/grant",new{ExpectedVersion=version},OrderContract.Json,Ct);Assert.Equal(HttpStatusCode.OK,r.StatusCode);return (await r.Content.ReadFromJsonAsync<DeliveryGrant>(OrderContract.Json,Ct))!;}
    private static Task<HttpResponseMessage> Content(HttpClient c,string id,string delivery,string? token)
    {var request=new HttpRequestMessage(HttpMethod.Get,PathFor(id)+"/deliveries/"+delivery+"/content");if(token is not null)request.Headers.Add("X-Delivery-Grant",token);return c.SendAsync(request,Ct);}
    [Fact] public async Task Tracking_routes_are_absent_until_separately_enabled()
    {using var s=Store();using var f=new RequestAuthorizationTests.Factory(commerceStore:s);using var c=f.Client(f.Token(scope:"orders:read"));using var r=await c.GetAsync(PathFor(Key())+"/tracking",Ct);Assert.Equal(HttpStatusCode.NotFound,r.StatusCode);}
    [Fact] public async Task Tracking_and_revision_use_dedicated_permissions_and_owner_predicates()
    {using var s=Store();var ready=Ready(s);using var f=new RequestAuthorizationTests.Factory(commerceStore:s,fulfillment:true);using var anonymous=f.Client();using var unauth=await anonymous.GetAsync(PathFor(ready.Id)+"/tracking",Ct);Assert.Equal(HttpStatusCode.Unauthorized,unauth.StatusCode);using var wrong=f.Client(f.Token());using var forbidden=await wrong.GetAsync(PathFor(ready.Id)+"/tracking",Ct);Assert.Equal(HttpStatusCode.Forbidden,forbidden.StatusCode);using var b=f.Client(f.Token(subject:"reader-b",scope:"orders:read orders:write"));using var other=await b.GetAsync(PathFor(ready.Id)+"/tracking",Ct);Assert.Equal(HttpStatusCode.NotFound,other.StatusCode);using var revision=await b.PostAsJsonAsync(PathFor(ready.Id)+"/revisions",new RevisionCommand(3,Key(),"Foreign"),OrderContract.Json,Ct);Assert.Equal(HttpStatusCode.NotFound,revision.StatusCode);}
    [Fact] public async Task Owned_tracking_has_no_store_history_notes_and_durable_delivery_notice()
    {using var s=Store();var ready=Ready(s);s.RequestRevision(A,ready.Id,new(3,Key(),"Synthetic revision note"));s.PublishReviewForLab(ready.Id,4);s.PublishDeliveryForLab(ready.Id,5);using var f=new RequestAuthorizationTests.Factory(commerceStore:s,fulfillment:true);using var c=f.Client(f.Token(scope:"orders:read"));using var response=await c.GetAsync(PathFor(ready.Id)+"/tracking",Ct);Assert.Equal(HttpStatusCode.OK,response.StatusCode);Assert.Contains("no-store",response.Headers.CacheControl!.ToString());var t=await response.Content.ReadFromJsonAsync<OrderTracking>(OrderContract.Json,Ct);Assert.Equal(6,t!.Order.Version);Assert.Equal("Synthetic revision note",Assert.Single(t.Revisions).Note);Assert.Equal(OrderNoticeKind.Delivered,t.Notices[^1].Kind);Assert.Equal(6,t.History.Count);}
    [Fact] public async Task Revision_retry_returns_one_receipt_and_new_stale_operation_conflicts()
    {using var s=Store();var ready=Ready(s);using var f=new RequestAuthorizationTests.Factory(commerceStore:s,fulfillment:true);using var c=f.Client(f.Token(scope:"orders:write"));var command=new RevisionCommand(3,Key(),"Synthetic");using var first=await c.PostAsJsonAsync(PathFor(ready.Id)+"/revisions",command,OrderContract.Json,Ct);s.PublishReviewForLab(ready.Id,4);using var again=await c.PostAsJsonAsync(PathFor(ready.Id)+"/revisions",command,OrderContract.Json,Ct);Assert.Equal(HttpStatusCode.OK,again.StatusCode);Assert.Equal(await first.Content.ReadFromJsonAsync<RevisionReceipt>(OrderContract.Json,Ct),await again.Content.ReadFromJsonAsync<RevisionReceipt>(OrderContract.Json,Ct));using var stale=await c.PostAsJsonAsync(PathFor(ready.Id)+"/revisions",command with{OperationKey=Key()},OrderContract.Json,Ct);Assert.Equal(HttpStatusCode.Conflict,stale.StatusCode);Assert.Single(s.TrackOrder(A,ready.Id).Revisions);}
    [Theory][InlineData("owner")][InlineData("state")][InlineData("price")]
    public async Task Revision_does_not_accept_forged_authority_fields(string field)
    {using var s=Store();var ready=Ready(s);using var f=new RequestAuthorizationTests.Factory(commerceStore:s,fulfillment:true);using var c=f.Client(f.Token(scope:"orders:write"));var text=JsonSerializer.Serialize(new RevisionCommand(3,Key(),"Synthetic"),OrderContract.Json);using var body=new StringContent(text[..^1]+",\""+field+"\":\"forged\"}",Encoding.UTF8,"application/json");using var response=await c.PostAsync(PathFor(ready.Id)+"/revisions",body,Ct);Assert.Equal(HttpStatusCode.BadRequest,response.StatusCode);Assert.Empty(s.TrackOrder(A,ready.Id).Revisions);}
    [Fact] public async Task List_is_owned_bounded_and_rejects_unknown_or_invalid_cursor_queries()
    {using var s=Store();Accept(s);using var f=new RequestAuthorizationTests.Factory(commerceStore:s,fulfillment:true);using var a=f.Client(f.Token(scope:"orders:read"));using var b=f.Client(f.Token(subject:"reader-b",scope:"orders:read"));Assert.Single((await a.GetFromJsonAsync<OrderPage>("/api/v1/commerce/orders",OrderContract.Json,Ct))!.Items);Assert.Empty((await b.GetFromJsonAsync<OrderPage>("/api/v1/commerce/orders",OrderContract.Json,Ct))!.Items);foreach(var query in new[]{"?after=../secret","?limit=9999","?after="+Key()+"&after="+Key()}){using var r=await a.GetAsync("/api/v1/commerce/orders"+query,Ct);Assert.Equal(HttpStatusCode.BadRequest,r.StatusCode);}}
    [Fact] public async Task Actual_request_to_revision_to_private_audio_journey_uses_production_client()
    {
        using var s=Store();using var f=new RequestAuthorizationTests.Factory(commerceStore:s,fulfillment:true);using var c=f.Client(f.Token(scope:"orders:read orders:write"));
        using var quoted=await c.PostAsJsonAsync("/api/v1/commerce/quotes",new QuoteCommand(Draft()),OrderContract.Json,Ct);var q=(await quoted.Content.ReadFromJsonAsync<OrderQuote>(OrderContract.Json,Ct))!;using var accepted=await c.PostAsJsonAsync("/api/v1/commerce/orders",new AcceptOrderCommand(q.Id,Key(),q.Request),OrderContract.Json,Ct);var order=(await accepted.Content.ReadFromJsonAsync<OrderSnapshot>(OrderContract.Json,Ct))!;PayAndStart(s,order);s.PublishReviewForLab(order.Id,2);
        var settings=new ApiSessionSettings(new("fixture.auth0.com","public-client-id"),"https://gnazzosworld.example/api",new("https://localhost/"));var session=new ApiSession(settings,new Vault(new(settings.Identity.Issuer,"reader-a",settings.Audience,f.Token(scope:"orders:read orders:write"),null,DateTimeOffset.UtcNow.AddMinutes(20))),new Provider(),TimeProvider.System);
        using var api=new TrackingApiClient(session,f.Server.CreateHandler(),clock);using var journal=new PendingRevisionDatabase(System.IO.Path.Combine(root,"journal.db"));var owner=await session.AcquireOwnedAsync(Ct);Assert.Single((await api.ListAsync(null,owner,Ct)).Items);var ready=await api.TrackAsync(order.Id,owner,Ct);var receipt=await new RevisionCoordinator(api,journal).SubmitAsync(order.Id,ready.Order.Version,"Invented lyric change",owner,Ct);Assert.Equal(4,receipt.AppliedVersion);s.PublishReviewForLab(order.Id,4);s.PublishDeliveryForLab(order.Id,5);var tracking=await api.TrackAsync(order.Id,owner,Ct);using var audio=await api.FetchAsync(order.Id,tracking.Deliveries.Single(),tracking.Order.Version,owner,Ct);Assert.Equal("RIFF",Encoding.ASCII.GetString(audio.Bytes.Span[..4]));Assert.Equal(PrivateDeliveryFixture.Sha256,Convert.ToHexString(SHA256.HashData(audio.Bytes.Span)).ToLowerInvariant());Assert.Equal(OrderState.Delivered,tracking.Order.State);Assert.Equal(OrderNoticeKind.Delivered,tracking.Notices[^1].Kind);
    }
    [Fact] public async Task Private_file_requires_credential_owner_and_grant_then_has_exact_hash_and_no_store()
    {using var s=Store();var ready=Ready(s);var d=s.PublishDeliveryForLab(ready.Id,3);using var f=new RequestAuthorizationTests.Factory(commerceStore:s,fulfillment:true);using var a=f.Client(f.Token(scope:"orders:read"));var g=await Grant(a,ready.Id,d);using var anonymous=f.Client();using var denied=await Content(anonymous,ready.Id,d.Id,g.Token);Assert.Equal(HttpStatusCode.Unauthorized,denied.StatusCode);using var b=f.Client(f.Token(subject:"reader-b",scope:"orders:read"));using var foreign=await Content(b,ready.Id,d.Id,g.Token);Assert.Equal(HttpStatusCode.NotFound,foreign.StatusCode);using var missing=await Content(a,ready.Id,d.Id,null);Assert.Equal(HttpStatusCode.NotFound,missing.StatusCode);using var response=await Content(a,ready.Id,d.Id,g.Token);Assert.Equal(HttpStatusCode.OK,response.StatusCode);Assert.Contains("no-store",response.Headers.CacheControl!.ToString());Assert.Equal("nosniff",Assert.Single(response.Headers.GetValues("X-Content-Type-Options")));Assert.Equal(PrivateDeliveryFixture.Length,response.Content.Headers.ContentLength);Assert.Equal(PrivateDeliveryFixture.Sha256,Convert.ToHexString(SHA256.HashData(await response.Content.ReadAsByteArrayAsync(Ct))).ToLowerInvariant());}
    [Fact] public async Task Expiry_revocation_and_wrong_delivery_route_reject_previously_issued_grant()
    {using var s=Store();var ready=Ready(s);var d=s.PublishDeliveryForLab(ready.Id,3);using var f=new RequestAuthorizationTests.Factory(commerceStore:s,fulfillment:true);using var c=f.Client(f.Token(scope:"orders:read"));var g=await Grant(c,ready.Id,d);using var wrong=await Content(c,ready.Id,Key(),g.Token);Assert.Equal(HttpStatusCode.NotFound,wrong.StatusCode);clock.Now=g.ExpiresAt;using var expired=await Content(c,ready.Id,d.Id,g.Token);Assert.Equal(HttpStatusCode.NotFound,expired.StatusCode);var renewed=await Grant(c,ready.Id,d);s.RevokeDeliveryForLab(ready.Id,d.Id,4);using var revoked=await Content(c,ready.Id,d.Id,renewed.Token);Assert.Equal(HttpStatusCode.NotFound,revoked.StatusCode);}
    [Fact] public async Task Private_endpoint_rejects_query_capabilities_range_and_public_static_paths()
    {using var s=Store();var ready=Ready(s);var d=s.PublishDeliveryForLab(ready.Id,3);using var f=new RequestAuthorizationTests.Factory(commerceStore:s,fulfillment:true);using var c=f.Client(f.Token(scope:"orders:read"));var g=await Grant(c,ready.Id,d);using var query=await c.GetAsync(PathFor(ready.Id)+"/deliveries/"+d.Id+"/content?token="+g.Token,Ct);Assert.Equal(HttpStatusCode.BadRequest,query.StatusCode);using var rangeRequest=new HttpRequestMessage(HttpMethod.Get,PathFor(ready.Id)+"/deliveries/"+d.Id+"/content");rangeRequest.Headers.Add("X-Delivery-Grant",g.Token);rangeRequest.Headers.Range=new(0,10);using var ranged=await c.SendAsync(rangeRequest,Ct);Assert.Equal(HttpStatusCode.BadRequest,ranged.StatusCode);using var publicPath=await c.GetAsync("/Fixtures/delivery_sample.wav",Ct);Assert.Equal(HttpStatusCode.NotFound,publicPath.StatusCode);}
    private sealed class Clock:TimeProvider{public DateTimeOffset Now=new(2026,11,16,12,0,0,TimeSpan.Zero);public override DateTimeOffset GetUtcNow()=>Now;}
    private sealed class Vault(SessionGrant grant):ISessionVault{private SessionGrant? value=grant;public Task<SessionGrant?> ReadAsync(CancellationToken ct)=>Task.FromResult(value);public Task WriteAsync(SessionGrant? v,CancellationToken ct){value=v;return Task.CompletedTask;}}
    private sealed class Provider:ISessionProvider{public Task<SessionGrant> SignInAsync(CancellationToken ct)=>throw new InvalidOperationException();public Task<SessionGrant> RefreshAsync(SessionGrant previous,CancellationToken ct)=>throw new InvalidOperationException();}
    public void Dispose(){if(Directory.Exists(root))Directory.Delete(root,true);}
}
